from pathlib import Path
import re
P=Path('/home/imo/HeCBench_julia/src/mmcsf-julia');s=(P/'mmcsf-julia-cuda.jl/main.jl').read_text();s=s.replace('using CUDA,Libdl,SHA','using CUDA,Libdl,SHA,KernelAbstractions\nconst MM_BACKEND=CUDA.CUDABackend(always_inline=true)');s=s.replace('include(joinpath(@__DIR__,"device_bodies.jl"))','include(joinpath(@__DIR__,"..","mmcsf-julia-cuda.jl","device_bodies.jl"))');s=re.sub(r'function mm_kernel(\d)\(([^\n]*)\)',r'@kernel unsafe_indices=true function mm_kernel\1(\2,bd)',s);s=s.replace('Int64(threadIdx().x)-1,Int64(blockIdx().x)-1,Int64(blockDim().x)','Int64(@index(Local,Linear))-1,Int64(@index(Group,Linear))-1,bd');s=s.replace('    return\n','    nothing\n');s=re.sub(r'@cuda threads=Int\(q.block\) blocks=Int\(q.grid\) stream=MM_STREAM mm_kernel(\d)\(([^\n]*)\)',r'mm_kernel\1(MM_BACKEND,Int(q.block))(\2,Int64(q.block);ndrange=Int(q.block)*Int(q.grid))',s);(P/'mmcsf-julia-KA/main.jl').write_text(s)
